        self.flagKey = flagKey
        self.flagType = flagType
        self.value = value
        self.defaultValue = defaultValue
        self.variant = variant
        self.reason = reason
        self.ruleId = ruleId
        self.errorCode = errorCode
        self.evaluatedAt = evaluatedAt
    }

    

    
}

